const BRANCH_ANCHORS_V5 = (() => {
  const arr = [];
  for (let i = 0; i < BRANCH_PIXELS_V5.length; i += 4) {
    const px = BRANCH_PIXELS_V5[i];
    const py = BRANCH_PIXELS_V5[i + 1];
    const angle = BRANCH_PIXELS_V5[i + 2];
    const behind = BRANCH_PIXELS_V5[i + 3] === 1;
    const svg = photoToSvg(px, py);
    arr.push({ x: svg.x, y: svg.y, angle, behind });
  }
  return arr;
})();

export const LEAF_ANCHORS_V5 = interleaveByTier(
  BRANCH_ANCHORS_V5.filter((a) => !a.behind),
  BRANCH_ANCHORS_V5.filter((a) => a.behind)
);

