export function getLeafV5(index) {
  const anchor = LEAF_ANCHORS_V5[index % LEAF_ANCHORS_V5.length];
  const ring = Math.floor(index / LEAF_ANCHORS_V5.length);
  const rand = seededRandom(index * 2654435761 + 7);
  const anchorAngleRad = (anchor.angle * Math.PI) / 180;
  let jitterAngle;
  let radius;
  if (ring === 0) {
    jitterAngle = rand() * Math.PI * 2;
    radius = 0.8 + rand() * 0.8;
  } else {
    jitterAngle = anchorAngleRad + (rand() - 0.5) * Math.PI * 0.9;
    radius = 1 + Math.min(ring * 0.3, 4) + rand() * 0.9;
  }
  const variant = LEAF_IMAGES_V5[index % LEAF_IMAGES_V5.length];
  const jitterRot = (rand() - 0.5) * 50;
  // 대부분은 가지 바깥쪽을 향하되, 일부(대략 5개 중 1개)는 180도 뒤집어서 아래로 처진
  // (드루핑) 잎도 섞이게 함 — 실제 나무도 잎이 전부 바깥쪽만 향하지 않고 중력에 눌려
  // 안쪽/아래로 처진 잎이 섞여 있음
  const droop = rand() < 0.22 ? 180 : 0;
  const rot = anchor.angle + 90 - (variant.stemAngle * 180) / Math.PI + jitterRot + droop;
  // 절반은 좌우로 뒤집어서, 잎 스프라이트 자체에 한쪽으로 쏠린 결이 있어도 섞이게 함
  const flip = rand() < 0.5;
  return {
    x: anchor.x + Math.cos(jitterAngle) * radius,
    y: anchor.y + Math.sin(jitterAngle) * radius * 0.85,
    rot,
    flip,
    scale: 0.55 + rand() * 0.3,
    variant,
    behind: anchor.behind,
  };
}

export const FRUIT_SPOTS_V5 = LEAF_ANCHORS_V5.filter((_, i) => i % 6 === 0).map((a) => ({ x: a.x, y: a.y, behind: a.behind }));
